import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import '../styles/simad.css';

/*
 * SimAd — a clickbait-style ad banner used by the PHISHBOOK training
 * simulation. It is intentionally designed to look like an ordinary
 * e-commerce voucher card (the kind used in real phishing lures) but it
 * never collects any data and never leaves the app. Clicking it always
 * routes to /sim/ad-landing, which reveals the simulation and walks
 * through the red flags.
 *
 * Branded "Shoppa" — a fictional shopping brand invented for this
 * exercise. It is not Shopee or any other real retailer; it only uses
 * the generic orange "voucher card" look common to e-commerce apps.
 *
 * Red flags on purpose: unsolicited "you got a voucher" message, a
 * countdown that is only a local timer (nothing actually expires), and
 * pressure to claim fast.
 */

const START_SECONDS = 10 * 60;
const pad = (n) => String(n).padStart(2, '0');

export default function SimAd({ variant = 'default' }) {
  const navigate = useNavigate();
  const [left, setLeft] = useState(START_SECONDS);

  // Cosmetic countdown only — nothing is tied to it.
  useEffect(() => {
    const id = setInterval(() => setLeft((s) => (s > 0 ? s - 1 : 0)), 1000);
    return () => clearInterval(id);
  }, []);

  return (
    <button
      type="button"
      className={`sim-ad sim-ad-${variant}`}
      onClick={() => navigate('/sim/ad-landing')}
      aria-label="Sponsored: claim your 1,000 peso Shoppa voucher"
    >
      <span className="sim-ad-stub" aria-hidden="true">
        <span className="sim-ad-stub-amt"><small>₱</small>1,000</span>
        <span className="sim-ad-stub-off">OFF</span>
      </span>

      <span className="sim-ad-main">
        <span className="sim-ad-title">Shoppa sent you a voucher</span>
        <span className="sim-ad-sub">
          No minimum spend · claim within {pad(Math.floor(left / 60))}:{pad(left % 60)}
        </span>
        <span className="sim-ad-meta">Sponsored</span>
      </span>

      <span className="sim-ad-cta">Claim</span>
    </button>
  );
}
